using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using TMPro;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckSkeeBall.Editor {
public static class SkeeAuthoring {
 public const string Folder="TruckSkeeBall",Scene="Assets/TruckSkeeBall/Scenes/TruckSkeeBall.unity";
 public static void Create(){var m=SportsEventAuthoring.Begin<SkeeMatch>(Folder);Directory.CreateDirectory("Assets/"+Folder+"/Models");AssetDatabase.Refresh();m.option=0;m.setup.count=4;m.NormalizeSetup();m.feedback.clips=(AudioClip[])LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create().Clone();m.feedback.clips[5]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckDockDiving/Audio/Exceptional cheer.wav");var wood=SportsEventAuthoring.Mat(Folder,"Arcade polished maple",new Color(.77f,.47f,.2f),.42f);var maple=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckBowling/Materials/Maple lane.mat");if(maple!=null&&maple.mainTexture!=null)wood.mainTexture=maple.mainTexture;var contact=SportsEventAuthoring.Contact(Folder,"Skee runway rolling contact",.65f,.03f);var boardContact=SportsEventAuthoring.Contact(Folder,"Arcade target solid contact",.32f,.13f);var metal=SportsEventAuthoring.Mat(Folder,"Arcade navy painted metal",new Color(.025f,.045f,.085f),.55f);metal.SetFloat("_Metallic",.5f);var light=SportsEventAuthoring.Mat(Folder,"Warm scoring ring lights",new Color(1,.83f,.37f),.45f);light.EnableKeyword("_EMISSION");light.SetColor("_EmissionColor",Color.black);var felt=SportsEventAuthoring.Mat(Folder,"Recessed return collector",new Color(.17f,.025f,.035f),.1f);m.courses=new SkeeRunner[4];m.arenas=new Transform[4];var flare=SportsChaosAuthoring.Flare(Folder);var font=SportsBroadcastAuthoring.Theme().headingFont;
 for(int lane=0;lane<4;lane++){float x=lane*38;var root=new GameObject("Equivalent giant arcade Skee course "+(lane+1)).transform;m.arenas[lane]=root;var points=new[]{new Vector3(x,0,-2),new Vector3(x,0,24),new Vector3(x,0,32),new Vector3(x,.8f,37),new Vector3(x,2.9f,41),new Vector3(x,4.9f,42.5f),new Vector3(x,7.1f,44)};var road=SportsEasyRoadsAuthoring.Bake(Folder,"Curved arcade launch ramp "+lane,points,10,wood,contact);road.SetParent(root,true);SportsEventAuthoring.Box("Course miss floor",new Vector3(x,-3.6f,50),new Vector3(36,.5f,125),metal,contact,root);for(int side=-1;side<=1;side+=2){SportsEventAuthoring.Box("Physical approach side rail",new Vector3(x+side*5.35f,.22f,15),new Vector3(.4f,.6f,35),metal,contact,root);for(int z=4;z<=28;z+=8){var strip=SportsEventAuthoring.Box("Learnable approach speed reference",new Vector3(x,.014f,z),new Vector3(8,.018f,.15f),light,null,root);}}var board=new GameObject("Real open-hole inclined arcade target").transform;board.SetParent(root,false);board.position=new Vector3(x,2,68);board.rotation=Quaternion.Euler(35,0,0);board.gameObject.AddComponent<SkeeBoard>();var rings=new List<SkeeRing>();for(int row=0;row<5;row++)for(int col=-1;col<=1;col++){bool hole=col==0||row==4;var center=new Vector2(col*8,row*7+3.5f);int pointsValue=col==0?new[]{10,20,30,40,50}[row]:100;float radius=col==0?new[]{3.35f,2.9f,2.5f,2.15f,1.9f}[row]:1.9f;if(!hole){SportsEventAuthoring.Box("Modeled maple target panel",new Vector3(center.x,center.y,0),new Vector3(8,7,.36f),wood,boardContact,board);continue;}var g=new GameObject("Actual "+pointsValue+" point circular opening");g.transform.SetParent(board,false);g.transform.localPosition=new Vector3(center.x,center.y,0);var mesh=Panel("Open maple panel "+row+" "+col,radius,4,3.5f,true);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=wood;var solid=g.AddComponent<MeshCollider>();solid.sharedMesh=mesh;solid.sharedMaterial=boardContact;var ring=g.AddComponent<SkeeRing>();ring.points=pointsValue;ring.radius=radius;ring.center=center;var bezel=new GameObject("Animated rolled scoring rim");bezel.transform.SetParent(g.transform,false);var rim=Panel("Rolled illuminated rim "+radius.ToString("F2"),radius,radius+.15f,radius+.15f,false);bezel.AddComponent<MeshFilter>().sharedMesh=rim;ring.lightRing=bezel.AddComponent<MeshRenderer>();ring.lightRing.sharedMaterial=light;var rimCollider=bezel.AddComponent<MeshCollider>();rimCollider.sharedMesh=rim;rimCollider.sharedMaterial=boardContact;var collector=new GameObject("Deep physical hole collector");collector.transform.SetParent(g.transform,false);var collectorMesh=Collector(radius);collector.AddComponent<MeshFilter>().sharedMesh=collectorMesh;collector.AddComponent<MeshRenderer>().sharedMaterial=felt;var shell=collector.AddComponent<MeshCollider>();shell.sharedMesh=collectorMesh;shell.sharedMaterial=boardContact;rings.Add(ring);var label=new GameObject("Inlaid "+pointsValue+" point score").AddComponent<TextMeshPro>();label.transform.SetParent(g.transform,false);label.transform.localPosition=new Vector3(-3.25f,2.6f,-.25f);label.transform.localScale=Vector3.one*.18f;label.rectTransform.sizeDelta=new Vector2(7,3);label.font=font;label.fontSize=28;label.text=pointsValue.ToString();label.alignment=TextAlignmentOptions.Center;label.color=new Color(1,.86f,.5f);}
 for(int side=-1;side<=1;side+=2)SportsEventAuthoring.Box("Arcade cabinet side structure",new Vector3(side*12.3f,17.5f,1.5f),new Vector3(.6f,36,3.5f),metal,boardContact,board);SportsEventAuthoring.Box("Arcade marquee",new Vector3(0,36.7f,.5f),new Vector3(25,2.3f,2),metal,null,board);var title=new GameObject("SKEE BALL arcade marquee lettering").AddComponent<TextMeshPro>();title.transform.SetParent(board,false);title.transform.localPosition=new Vector3(0,36.7f,-.6f);title.transform.localScale=Vector3.one*.25f;title.rectTransform.sizeDelta=new Vector2(70,8);title.font=font;title.fontSize=28;title.text="TRUCK SKEE-BALL";title.alignment=TextAlignmentOptions.Center;title.color=new Color(1,.5f,.04f);
 var t=SportsEventAuthoring.Truck(m,Folder,"Skee truck lane "+(lane+1),new Vector3(x,.7f,2),lane);SportsRallyAuthoring.FitTruck(t);t.maxSpeed=34;t.motorTorque=16;t.steerAngle=27;t.grip=1.35f;t.body.angularDamping=.12f;t.body.maxAngularVelocity=10;foreach(var renderer in t.visuals.GetComponentsInChildren<Renderer>(true))renderer.gameObject.layer=10+lane;var runner=t.gameObject.AddComponent<SkeeRunner>();runner.match=m;runner.lane=lane;runner.owner=lane;runner.truck=t;runner.target=board;runner.rings=rings.ToArray();runner.viewCamera=SportsEventAuthoring.Camera("Independent Skee driver camera "+lane);runner.viewCamera.view.fieldOfView=75;runner.viewCamera.view.farClipPlane=220;runner.viewCamera.view.enabled=lane==0;runner.viewCamera.Pose(new Vector3(x,.7f,2),new Vector3(7,7,-12),66,true);SportsChaosAuthoring.Cab(runner.viewCamera.view,Folder,lane,25);var interior=runner.viewCamera.transform.Find("Driver seat interior");runner.cabAnchor=new GameObject("Stable own Skee cab anchor "+lane).transform;interior.SetParent(runner.cabAnchor,false);runner.cabAnchor.gameObject.SetActive(false);runner.viewCamera.cabSteering.Bind(t);runner.look=runner.viewCamera.gameObject.AddComponent<SportsCabLook>();runner.replay=SportsRallyAuthoring.Replay(m,new[]{t.transform});runner.replay.capacity=1200;runner.replay.maximumReplayAge=10;foreach(var renderer in runner.replay.ghosts[0].GetComponentsInChildren<Renderer>(true))renderer.gameObject.layer=10+lane;runner.celebration=new GameObject("Bounded ring celebration "+lane).AddComponent<ParticleSystem>();SportsChaosAuthoring.FixBlast(runner.celebration,flare);m.courses[lane]=runner;}
 m.cameras=new[]{m.courses[0].viewCamera.view};SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);SportsBroadcastAuthoring.ApplyScene();SportsEventAuthoring.Save(Folder);Validate();}
 static Mesh Save(string name,Vector3[] vertices,int[] triangles){string path="Assets/"+Folder+"/Models/"+name+".asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){mesh=new Mesh{name=name};AssetDatabase.CreateAsset(mesh,path);}mesh.Clear();mesh.vertices=vertices;mesh.triangles=triangles;mesh.uv=vertices.Select(v=>new Vector2(v.x,v.y)*.15f).ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);return mesh;}
 static Mesh Panel(string name,float radius,float halfWidth,float halfHeight,bool rectangular){const int n=96;var vertices=new Vector3[n*4];var triangles=new List<int>();for(int ring=0;ring<4;ring++)for(int i=0;i<n;i++){float a=i*Mathf.PI*2/n;float c=Mathf.Cos(a),s=Mathf.Sin(a);float outer=rectangular?Mathf.Min(halfWidth/Mathf.Max(.0001f,Mathf.Abs(c)),halfHeight/Mathf.Max(.0001f,Mathf.Abs(s))):halfWidth;float r=ring==0||ring==3?radius:outer;vertices[ring*n+i]=new Vector3(c*r,s*r,ring<2?-.18f:.18f);int next=(i+1)%n,back=(ring+1)%4*n;triangles.AddRange(new[]{ring*n+i,ring*n+next,back+i,ring*n+next,back+next,back+i});}return Save(name,vertices,triangles.ToArray());}
 static Mesh Collector(float radius){const int n=96;var vertices=new List<Vector3>();for(int row=0;row<2;row++)for(int i=0;i<n;i++){float a=i*Mathf.PI*2/n;vertices.Add(new Vector3(Mathf.Cos(a)*radius*(row==0?1:.9f),Mathf.Sin(a)*radius*(row==0?1:.9f),row==0?.18f:3.5f));}vertices.Add(new Vector3(0,0,3.5f));var tris=new List<int>();for(int i=0;i<n;i++){int j=(i+1)%n;tris.AddRange(new[]{i,n+i,j,j,n+i,n+j,2*n,n+j,n+i});}return Save("Deep return collector "+radius.ToString("F2"),vertices.ToArray(),tris.ToArray());}
 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<SkeeMatch>();if(m==null){EditorSceneManager.OpenScene(Scene);m=UnityEngine.Object.FindAnyObjectByType<SkeeMatch>();}if(m==null||m.courses.Length!=4||m.arenas.Length!=4)throw new Exception("Four equivalent Skee courses required");foreach(var r in m.courses)if(r.rings.Length!=7||r.look==null||r.cabAnchor==null||r.replay.sources.Length!=1||r.rings.Any(h=>h.GetComponent<MeshCollider>()==null||h.radius<1.8f))throw new Exception("Physical opening/cab/replay references missing");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("One Skee listener required");Debug.Log("SKEE_NATIVE_SCENE_VALIDATED");}
}}
